// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * Open-addressing memo from a fixed-arity tuple of slot values to a boolean verdict.
 * <p>
 * The keys live in one flat {@code long[]} at a fixed stride, so a stored key costs no object: the general
 * {@code HashMap<GroupKey, Boolean>} form it replaces allocated a {@code GroupKey} plus a boxed value plus a map node
 * per distinct key, and hashed through {@code Arrays.hashCode}. Probing reads the caller's row directly, so a lookup
 * that misses never materialises a key at all.
 * <p>
 * Occupancy is tracked in a side array rather than by reserving a key value, so every {@code long} - including
 * {@link Long#MIN_VALUE} and zero - is a storable slot value. Not thread-safe: one memo belongs to one cursor.
 */
final class LongVerdictMemo {

	/** Returned by {@link #get} when the tuple has no recorded verdict. */
	static final int ABSENT = -1;

	private static final byte EMPTY = 0;
	private static final byte FALSE = 1;
	private static final byte TRUE = 2;

	private static final long MIX = 0x9e3779b97f4a7c15L;

	private final int arity;
	private long[] keys;
	private byte[] states;
	private int mask;
	private int size;
	private int growAt;

	LongVerdictMemo(int arity) {
		this(arity, 1 << 10);
	}

	LongVerdictMemo(int arity, int initialCapacity) {
		if (arity < 1) {
			throw new IllegalArgumentException("memo arity must be positive: " + arity);
		}
		this.arity = arity;
		int capacity = Integer.highestOneBit(Math.max(16, initialCapacity - 1)) << 1;
		keys = new long[Math.multiplyExact(capacity, arity)];
		states = new byte[capacity];
		mask = capacity - 1;
		growAt = capacity - (capacity >>> 2); // grow at 75% load
	}

	/** Returns {@code 1} for a recorded true verdict, {@code 0} for false, or {@link #ABSENT}. */
	int get(long[] row, int[] slots) {
		int index = slotOf(row, slots);
		byte state = states[index];
		if (state == EMPTY) {
			return ABSENT;
		}
		return state == TRUE ? 1 : 0;
	}

	void put(long[] row, int[] slots, boolean verdict) {
		int index = slotOf(row, slots);
		if (states[index] == EMPTY) {
			int at = index * arity;
			for (int i = 0; i < arity; i++) {
				keys[at + i] = row[slots[i]];
			}
			states[index] = verdict ? TRUE : FALSE;
			if (++size >= growAt) {
				grow();
			}
			return;
		}
		states[index] = verdict ? TRUE : FALSE;
	}

	int size() {
		return size;
	}

	/** Index of the entry matching the probed tuple, or of the first empty slot on its probe sequence. */
	private int slotOf(long[] row, int[] slots) {
		int index = hash(row, slots) & mask;
		while (states[index] != EMPTY && !matches(index, row, slots)) {
			index = index + 1 & mask;
		}
		return index;
	}

	private boolean matches(int index, long[] row, int[] slots) {
		int at = index * arity;
		for (int i = 0; i < arity; i++) {
			if (keys[at + i] != row[slots[i]]) {
				return false;
			}
		}
		return true;
	}

	private void grow() {
		long[] oldKeys = keys;
		byte[] oldStates = states;
		int capacity = oldStates.length << 1;
		if (capacity <= 0) {
			throw new IllegalStateException("verdict memo exceeded the addressable table size");
		}
		keys = new long[Math.multiplyExact(capacity, arity)];
		states = new byte[capacity];
		mask = capacity - 1;
		growAt = capacity - (capacity >>> 2);
		for (int old = 0; old < oldStates.length; old++) {
			if (oldStates[old] == EMPTY) {
				continue;
			}
			int from = old * arity;
			int index = hashStored(oldKeys, from) & mask;
			while (states[index] != EMPTY) {
				index = index + 1 & mask;
			}
			System.arraycopy(oldKeys, from, keys, index * arity, arity);
			states[index] = oldStates[old];
		}
	}

	private int hash(long[] row, int[] slots) {
		long mixed = 0;
		for (int i = 0; i < arity; i++) {
			mixed = (mixed ^ row[slots[i]]) * MIX;
			mixed ^= mixed >>> 29;
		}
		return (int) (mixed ^ mixed >>> 32);
	}

	private int hashStored(long[] source, int at) {
		long mixed = 0;
		for (int i = 0; i < arity; i++) {
			mixed = (mixed ^ source[at + i]) * MIX;
			mixed ^= mixed >>> 29;
		}
		return (int) (mixed ^ mixed >>> 32);
	}
}
